    { version = "2.27.1",
      de = { "|cffffd100Berufsfenster|r: Die GuildPride-Leiste (AH: Zutaten, Zur Einkaufsliste, Kosten und Gewinn) steht jetzt mittig im rechten Bereich, unten direkt über dem Häkchen unter dem Rezept. Kosten und Gewinn bleiben in einer Zeile und werden bei Bedarf kleiner, damit sie hineinpassen" },
      en = { "|cffffd100Profession window|r: the GuildPride bar (AH: reagents, To shopping list, cost and profit) now sits centred in the right-hand section, at the bottom just above the checkbox below the recipe. Cost and profit stay on one line and shrink when needed so they fit" } },
    { version = "2.27.0",
      de = { "|cffffd100Flugzeiten|r: Am Flugmeister steht im Tooltip jedes Ziels, wie lange der Flug dauert – geschätzt wie bei Polestar (|cffffd100ca.|r), selbst geflogene Strecken mit der gemessenen Zeit in Gold. Jeder eigene Flug wird gestoppt und gemerkt", "|cffffd100Flug-Zähler|r: Während des Flugs zeigt ein verschiebbares Fenster Ziel, Restzeit bis zur Landung und einen Balken. Beides lässt sich in den Einstellungen (Reisen) abschalten", "|cffffd100Schwarzes Brett für bestimmte Ränge|r: Beim Aushang (Reiter Verwaltung) wählst du per Häkchen, welche Ränge ihn sehen. Alle angekreuzt = für alle", "|cffffd100Item-ID im Tooltip|r: neuer Schalter in den Einstellungen (Allgemein), standardmäßig aus", "|cffffd100Auktionshaus – Stufenbereich|r: In der Suche lässt sich die Stufe von – bis eintragen; leer = ohne Grenze", "|cffffd100Berufsfenster|r: Kosten und Gewinn stehen jetzt unter den Knöpfen „AH: Zutaten“ und „Zur Einkaufsliste“", "|cffffd100Wunschliste|r: Umschalt+Klick auf ein Item fügt es ins Feld ein, ohne vorher hineinzuklicken" },
      en = { "|cffffd100Flight times|r: at the flight master each destination's tooltip shows how long the flight takes – estimated like Polestar (|cffffd100~|r), routes you have flown with the measured time in gold. Every flight of yours is timed and remembered", "|cffffd100Flight timer|r: while flying, a movable window shows destination, time left until landing and a bar. Both can be switched off in the settings (Travel)", "|cffffd100Bulletin board for chosen ranks|r: when posting (Manage tab) tick which ranks see it. All ticked = everyone", "|cffffd100Item ID in the tooltip|r: new switch in the settings (General), off by default", "|cffffd100Auction house – level range|r: the search takes a level from – to; empty = no limit", "|cffffd100Profession window|r: cost and profit now sit below the \"AH: reagents\" and \"To shopping list\" buttons", "|cffffd100Wish list|r: shift-click on an item puts it into the field without clicking into it first" } },
    { version = "2.26.1",
      de = { "|cffffd100Gildenfenster (J)|r: J öffnet immer genau ein Fenster – je nach Einstellung |cffffd100Dieses Fenster statt Blizzard-Gildenfenster|r GuildPride oder Blizzard. Vorher blieb Blizzards Fenster nach dem Abschalten unsichtbar, beim ersten J nach dem Einloggen gingen beide auf, und ein offenes GuildPride-Fenster blieb neben Blizzards stehen", "|cffffd100Auktionshaus – Komplett-Scan|r: nur alle 15 Minuten, auch nach /reload und für alle Charaktere; Scans von Auctionator zählen mit. Der Knopf bleibt bis dahin aus und zeigt die Wartezeit", "|cffffd100Auktionshaus – weniger Ruckeln|r: große Scan-Listen werden in kleineren Stücken gelesen und gespeichert und nicht mehr alle 30 Sekunden neu gelesen" },
      en = { "|cffffd100Guild window (J)|r: J always opens exactly one window – GuildPride or Blizzard, depending on |cffffd100Use this window instead of Blizzard's guild window|r. Before, Blizzard's window stayed invisible after switching off, both opened on the first J after login, and an open GuildPride window stayed next to Blizzard's", "|cffffd100Auction house – full scan|r: only every 15 minutes, even after /reload and across all characters; Auctionator scans count too. The button stays disabled until then and shows the wait", "|cffffd100Auction house – less stutter|r: large scan lists are read and saved in smaller chunks and no longer re-read every 30 seconds" } },
    { version = "2.26.0",
      de = { "|cffffd100Dungeons und Raids bei Gildenevents|r: Im Fenster |cffffd100Neues Event|r (Reiter Planen) gibt es bei |cffffd100Art|r je einen Knopf für Dungeon und Raid. Die Liste enthält alle Dungeons und Raids von WoW Forever mit Stufe und Spielerzahl; der Name wird als Titel übernommen. Die Event-Liste zeigt eine eigene Spalte (z. B. |cffffd100Raid · 40|r), die Aufstellung richtet sich nach der Gruppengröße, und an Discord geht die Auswahl mit, damit der Bot die passende Gruppe anlegt", "|cffffd100Teilen ohne Ausnahme|r: Schiffs- und Zeppelinzeiten, Rares und Auktionshauspreise werden immer mit allen GuildPride-Spielern geteilt – auch wenn die |cffffd100Serverweite Gruppensuche|r aus ist. Der Schalter gilt nur noch für Gruppensuche und Layer-Wechsel. Die Schalter „Schiffs-Fahrpläne teilen“ und „Rares teilen“ sind entfernt", "|cffffd100Schiffs-Zähler – Bestätigungen|r: Haben mehrere Spieler dieselbe Zeit gemessen, steht |cffffd1003× bestätigt|r dabei; eine einzelne abweichende Meldung verdrängt so eine Zeit nicht mehr", "|cffffd100Schiffs-Zähler – Erinnerung|r: Uhr-Symbol an einer Verbindung anklicken – 1 Minute vor der Abfahrt kommen Raid-Warnung und Ton, auch wenn du nicht mehr am Anleger bist", "|cffffd100Schiffs-Zähler – Layer automatisch|r: Der Layer wird jetzt auch über Händler, Flugmeister, Quest-NPCs, das weiche Ziel, Namensplaketten und die Ziele der Gruppe erkannt", "|cffffd100Schiffs-Zähler – nach dem Reset|r: Gibt es diese Woche noch keine Messung, steht die Zeit der letzten Woche als |cffffd100vermutet|r da, bis jemand neu misst", "|cffffd100Versuch|r: Aus den Kreaturen erkennt GuildPride, wann ein Layer gestartet ist. Passt das bei zwei gemessenen Layern zusammen, gibt es auch für Layer ohne Messung eine Zeit (|cffffd100geschätzt für deinen Layer|r)" },
      en = { "|cffffd100Dungeons and raids for guild events|r: the |cffffd100New event|r window (Plan tab) has a button each for dungeon and raid under |cffffd100Type|r. The list holds every WoW Forever dungeon and raid with level and player count; the name becomes the title. The event list shows its own column (e.g. |cffffd100Raid · 40|r), the lineup follows the group size, and the choice is sent to Discord so the bot creates the matching group", "|cffffd100Sharing without exception|r: ship and zeppelin times, rares and auction house prices are always shared with all GuildPride players – even with the |cffffd100Server-wide group finder|r off. That switch now only covers the group finder and layer switching. The \"share ship timetables\" and \"share rares\" switches are removed", "|cffffd100Ship timer – confirmations|r: when several players measured the same time it shows |cffffd100confirmed 3×|r; a single differing report no longer replaces such a time", "|cffffd100Ship timer – reminder|r: click the clock icon on a connection – 1 minute before departure you get a raid warning and a sound, even if you left the dock", "|cffffd100Ship timer – automatic layer|r: your layer is now also detected from vendors, flight masters, quest NPCs, the soft target, nameplates and your group's targets", "|cffffd100Ship timer – after the reset|r: if nobody has measured this week yet, last week's time shows as |cffffd100guessed|r until someone measures again", "|cffffd100Experiment|r: GuildPride reads from creatures when a layer started. If that matches on two measured layers, layers without a measurement get a time too (|cffffd100estimated for your layer|r)" } },
    { version = "2.25.0",
      de = { "|cffffd100Schiffs-Zähler je Layer|r: Jeder Layer fährt seine Schiffe und Zeppeline versetzt. Messungen merken sich jetzt den Layer (am Abfahrts- und Ziel-Steg), und das Fenster am Anleger zeigt die Zeiten |cffffd100deines|r Layers – wechselst du den Layer, wechselt die Anzeige mit", "|cffffd100Mit allen GuildPride-Spielern geteilt|r: Eigene Messungen gehen außer an die Gilde auch an alle im serverweiten GuildPride-Kanal. Fehlt am Anleger eine Messung für deinen Layer, fragt GuildPride die anderen selbst (nur mit |cffffd100Serverweite Gruppensuche|r an)", "Messungen gelten jetzt bis zur wöchentlichen Wartung statt 6 Stunden; das Fenster zeigt, wie alt sie sind und ob sie von deinem Layer stammen (|cffffd100dein Layer|r, |cffffd100Layer ?|r, |cffffd100evtl. anderer Layer|r)", "Tipp im Fenster: eine Kreatur anvisieren, damit GuildPride deinen Layer erkennt" },
      en = { "|cffffd100Ship timer per layer|r: every layer runs its ships and zeppelins offset. Measurements now remember the layer (at the departure and arrival dock), and the dock window shows the times of |cffffd100your|r layer – switch layers and the display follows", "|cffffd100Shared with all GuildPride players|r: your measurements go to your guild and to everyone in the server-wide GuildPride channel. If the dock has no measurement for your layer, GuildPride asks the others by itself (only with |cffffd100Server-wide group finder|r on)", "Measurements now last until the weekly maintenance instead of 6 hours; the window shows how old they are and whether they are from your layer (|cffffd100your layer|r, |cffffd100layer ?|r, |cffffd100maybe other layer|r)", "Tip in the window: target a creature so GuildPride detects your layer" } },
